 * @name scwin.grd_ReportDataList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_ReportDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_ReportDataList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.goAction === 'function') { await scwin.goAction(r["formCd"], r["formVer"], r["formAdmInstTpCd"], r["inqdisclsTpCd"], "0", r["formUpclssCd"], r["rsnClssCd"], r["applFormYn"], r["ldMktTpCd"], r["formWrtMethdTpCd"], r["byformUsrTpCd"], r["exmptObjDisclsYn"], r["ismulti"], r["editClssCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goAction (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goAction'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.oncellclick' });
    }
};


