 * @hidden N
*/
scwin.enterSearchForm = async function () {
    /* sdd-asis-lifecycle:begin enterSearchForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.goSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goSearch = async function () {
    /* sdd-asis-lifecycle:begin goSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!scwin.isCheckSelect('type')) {
        await alertE('담당기관을 선택하십시오.');
        return;
    }
    if (!scwin.isCheckSelect('class')) {
        await alertE('공시구분을 선택하십시오.');
        return;
    }
    blockLoading();
    const foldYn = $('#foldBt').hasClass('on') === true ? "Y" : "N";
    $c.util.getComponent('dma_goSearchReq').set('foldYn', foldYn);
    $c.util.getComponent('dma_goSearchReq').set('method', "searchReport");
    (document.frmReportSearch || { elements: [] }).action = "/discls/dsReport.do";
    await scwin.tx_goSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isCheckSelect
 * @author Inswave
 * @date 2026. 09. 29
 * @param checkType
 * @returns
 * @hidden N
*/
scwin.isCheckSelect = function (checkType) {
    /* sdd-asis-lifecycle:begin isCheckSelect — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (checkType === "type") {
        if (((!$c.util.getComponent('ipt_allType') || typeof $c.util.getComponent('ipt_allType').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_allType'), false) : ($c.util.getComponent('ipt_allType').getValue() != null && String($c.util.getComponent('ipt_allType').getValue()) !== '')) === true) {
            return true;
        }
        for (var i = 0; i < $c.util.getComponent('ipt_checkType').length; i++) {
            if ((String($c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).getValue() || '') !== '') === true) {
